/**
 *
 * DataTableColumnReorderTarget is a declarative drop-target that shows visual feedback
 * (via data attributes or a render-prop) while a column is being dragged over its wrapped region.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableColumnReorderTarget
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
export type DataTableColumnReorderTargetPassThroughType<E> = PassThroughType<DataTableColumnReorderTargetInstance, E>;
export interface DataTableColumnReorderTargetPassThrough {
    root?: DataTableColumnReorderTargetPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * State made available to the render-prop form of `children`.
 */
export interface DataTableColumnReorderTargetRenderState {
    /** True while another column is being dragged over this target. */
    isOver: boolean;
    /** Which side of this target the drop would land on; `null` when inactive. */
    side: 'start' | 'end' | null;
}
/**
 * Configuration input for the target. Exposed through the second generic slot of
 * `BaseComponentProps` so it follows the same pattern as other primitive components.
 */
export interface useDataTableColumnReorderTargetProps {
    /**
     * Column index for this target. When omitted, the index is resolved from the nearest
     * ancestor `<th>`'s sibling position. Provide explicitly only when the DOM structure
     * makes sibling-based resolution unreliable (e.g., portaled headers).
     */
    index?: number;
}
export interface DataTableColumnReorderTargetProps extends Omit<BaseComponentProps<DataTableColumnReorderTargetInstance, useDataTableColumnReorderTargetProps, DataTableColumnReorderTargetPassThrough, 'div'>, 'children'> {
    /**
     * Content rendered inside the target. Accepts a render-prop form
     * `(state) => ReactNode` for state-aware rendering.
     */
    children?: React.ReactNode | ((state: DataTableColumnReorderTargetRenderState) => React.ReactNode);
}
export interface DataTableColumnReorderTargetState {
    isOver: boolean;
    side: 'start' | 'end' | null;
}
export interface DataTableColumnReorderTargetExposes {
    datatable: DataTableRootInstance | undefined | null;
}
export type DataTableColumnReorderTargetInstance = ComponentInstance<DataTableColumnReorderTargetProps, DataTableColumnReorderTargetState, DataTableColumnReorderTargetExposes>;
